DROP POLICY IF EXISTS "agent trade document delete" ON public.dv_accounting_agent_trade_documents;
CREATE POLICY "agent delete unapproved trade documents" ON public.dv_accounting_agent_trade_documents FOR DELETE TO authenticated USING (NOT (upper(coalesce(match_status,'')) IN ('MATCH','APPROVED')) AND EXISTS (SELECT 1 FROM public.dv_accounting_agent_trade_submissions s WHERE s.id = submission_id AND s.status IN ('DRAFT','NEEDS_CHANGES','SUBMITTED','APPROVED') AND (s.submitted_by = auth.uid() OR s.agent_id = public.dv_accounting_my_agent_id()) AND NOT EXISTS (SELECT 1 FROM public.dv_accounting_transactions t WHERE t.id = s.transaction_id AND upper(coalesce(t.status,'')) = 'PAID' AND upper(coalesce(t.commission_payroll_status,'')) = 'PAID')));
DROP POLICY IF EXISTS "agent trade document update" ON public.dv_accounting_agent_trade_documents;
CREATE POLICY "agent update unapproved trade documents" ON public.dv_accounting_agent_trade_documents FOR UPDATE TO authenticated USING (NOT (upper(coalesce(match_status,'')) IN ('MATCH','APPROVED')) AND EXISTS (SELECT 1 FROM public.dv_accounting_agent_trade_submissions s WHERE s.id = submission_id AND s.status IN ('DRAFT','NEEDS_CHANGES','SUBMITTED','APPROVED') AND (s.submitted_by = auth.uid() OR s.agent_id = public.dv_accounting_my_agent_id()) AND NOT EXISTS (SELECT 1 FROM public.dv_accounting_transactions t WHERE t.id = s.transaction_id AND upper(coalesce(t.status,'')) = 'PAID' AND upper(coalesce(t.commission_payroll_status,'')) = 'PAID'))) WITH CHECK (uploaded_by = auth.uid() AND upper(coalesce(match_status,'PENDING')) = 'PENDING' AND EXISTS (SELECT 1 FROM public.dv_accounting_agent_trade_submissions s WHERE s.id = submission_id AND s.status IN ('DRAFT','NEEDS_CHANGES','SUBMITTED','APPROVED') AND (s.submitted_by = auth.uid() OR s.agent_id = public.dv_accounting_my_agent_id()) AND NOT EXISTS (SELECT 1 FROM public.dv_accounting_transactions t WHERE t.id = s.transaction_id AND upper(coalesce(t.status,'')) = 'PAID' AND upper(coalesce(t.commission_payroll_status,'')) = 'PAID')));
DROP POLICY IF EXISTS "trade docs delete own draft or admin" ON storage.objects;
CREATE POLICY "trade docs delete own unapproved or admin" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'dv-trade-documents' AND (public.dv_accounting_is_trade_admin() OR ((storage.foldername(name))[1] = auth.uid()::text AND EXISTS (SELECT 1 FROM public.dv_accounting_agent_trade_documents d JOIN public.dv_accounting_agent_trade_submissions s ON s.id = d.submission_id WHERE d.storage_path = objects.name AND NOT (upper(coalesce(d.match_status,'')) IN ('MATCH','APPROVED')) AND s.status IN ('DRAFT','NEEDS_CHANGES','SUBMITTED','APPROVED') AND (s.submitted_by = auth.uid() OR s.agent_id = public.dv_accounting_my_agent_id()) AND NOT EXISTS (SELECT 1 FROM public.dv_accounting_transactions t WHERE t.id = s.transaction_id AND upper(coalesce(t.status,'')) = 'PAID' AND upper(coalesce(t.commission_payroll_status,'')) = 'PAID'))));